const text=(x,y,t,s=17,a='middle')=>`<text x="${x}" y="${y}" fill="#f8f6f2" font-size="${s}" text-anchor="${a}">${t}</text>`;
const svg=(body,label)=>`<svg class="shell-diagram plant-diagram" viewBox="0 0 540 360" role="img" aria-label="${label}">${body}</svg>`;
export function leafFigure(w={}){let highlight=w.part||'all',fill=(id,c)=>highlight===id?'#edc89a':c;let body='<rect x="65" y="64" width="350" height="30" rx="8" fill="'+fill('epidermis','#b7c7b6')+'"/>';for(let i=0;i<9;i++)body+=`<rect x="${70+i*38}" y="103" width="31" height="82" rx="9" fill="${fill('palisade','#83a493')}" stroke="#cddbc9"/><g fill="#3d6a59"><ellipse cx="${80+i*38}" cy="127" rx="4" ry="9"/><ellipse cx="${92+i*38}" cy="151" rx="4" ry="9"/></g>`;for(let i=0;i<12;i++)body+=`<ellipse cx="${85+(i%4)*91+(Math.floor(i/4)%2)*8}" cy="${206+Math.floor(i/4)*35}" rx="24" ry="12" fill="${fill('spongy','#98b2a3')}"/>`;body+=`<rect x="320" y="206" width="70" height="19" rx="8" fill="${fill('xylem','#85adbb')}"/><rect x="320" y="229" width="70" height="17" rx="8" fill="${fill('phloem','#d79886')}"/><rect x="65" y="298" width="350" height="23" rx="7" fill="#b7c7b6"/><ellipse cx="232" cy="310" rx="20" ry="12" fill="${fill('guard','#6f9480')}"/><ellipse cx="279" cy="310" rx="20" ry="12" fill="${fill('guard','#6f9480')}"/>`;
const labels=[['A',430,68,390,78,'Epidermis'],['B',430,129,393,140,'Palisade'],['C',430,275,392,272,'Spongy'],['D',430,210,389,215,'Xylem'],['E',430,337,280,313,'Guard cells']];for(let[a,x,y,tx,ty,name]of labels)body+=`<path d="M${tx} ${ty}L${x-7} ${y-5}" stroke="#dce6e5"/>`+text(x,y,w.neutral?a:name,15,'start');return svg(body,w.neutral?'Unlabelled transverse leaf section with callouts A to E; colours symbolic':'Schematic transverse leaf section with tissue labels');}
export function rootFigure(w={}){let long=w.hair!=='short',result=w.result||'in';return svg(`<path d="M80 100H250Q290 100 300 135L${long?440:350} 145V190L300 192Q290 245 250 245H80Z" fill="#cbbb9d" stroke="#eed6b2" stroke-width="3"/><path d="M91 110H246Q280 110 290 146L${long?427:337} 154V180L290 182Q278 232 246 232H91Z" fill="#a58c78"/><ellipse cx="146" cy="178" rx="22" ry="18" fill="#d9a990"/>${w.revealed&&result!=='stopped'?`<path d="M${result==='out'?'265 174H440':'435 174H270'}" stroke="#f7e3bb" stroke-width="4"/><path d="M${result==='out'?'440 174l-15-9v18Z':'270 174l15-9v18Z'}" fill="#f7e3bb"/>`:''}${text(160,62,'Root-hair cell',22)}${text(425,263,'Soil solution',17)}${text(270,321,w.revealed?(result==='stopped'?'Active ion route stopped':result==='in'?'Net uptake into the cell':'Net water movement out'):'Predict, then compare',18)}${text(270,347,'Membrane and hair enlarged · symbolic particles',13)}`,'Root-hair uptake schematic; '+(w.kind||'water')+' route');}
export function tubeFigure(w={}){let ph=w.tissue==='phloem',body=`<rect x="160" y="35" width="200" height="270" rx="24" fill="${ph?'#c99586':'#b49b7c'}"/><rect x="190" y="35" width="140" height="270" fill="#2f4c5b"/>`;if(ph)for(let y of[126,216]){body+=`<path d="M190 ${y}H330" stroke="#e7bba5" stroke-width="12"/>`;for(let x=207;x<330;x+=29)body+=`<circle cx="${x}" cy="${y}" r="6" fill="#2f4c5b"/>`;}else if(w.lignin!==false)for(let y=55;y<300;y+=38)body+=`<path d="M158 ${y}H190M330 ${y}H362" stroke="#e5c7a1" stroke-width="8"/>`;const down=w.direction==='down';body+=`<path d="M260 ${down?70:273}V${down?273:70}" stroke="${ph?'#efbc92':'#9bc2d1'}" stroke-width="5"/><path d="M260 ${down?273:70}l-10 ${down?-16:16}h20Z" fill="${ph?'#efbc92':'#9bc2d1'}"/>`+text(260,339,ph?'Dissolved sugar through porous ends':'Water + mineral ions through hollow lumen',17);return svg(body,(ph?'Phloem elongated cells and porous end walls':'Xylem hollow lignified vessel')+' schematic');}
export function stomaFigure(w={}){let open=w.open!==false,gap=open?28:3;return svg(`<rect x="42" y="54" width="456" height="235" rx="25" fill="#9aafa255" stroke="#bfd0c1"/><ellipse cx="${270-gap-35}" cy="172" rx="58" ry="96" fill="#84aa92"/><ellipse cx="${270+gap+35}" cy="172" rx="58" ry="96" fill="#84aa92"/><ellipse cx="270" cy="172" rx="${open?31:3}" ry="75" fill="#203b4b"/>${text(270,35,open?'Open pore':'Closed pore',22)}${text(270,327,open?'CO₂ entry and water-vapour loss possible':'Reduced water loss; less CO₂ entry',17)}${text(270,351,'Guard-cell shape and pore size are symbolic',13)}`,`${open?'Open':'Closed'} stomatal pore surrounded by paired guard cells`);}
export function wholeFigure(w={}){let dir=w.direction||'up',sugar=w.cargo==='sugar';return svg(`<path d="M267 70V270M267 253L180 316M267 253L350 316M267 143L160 103M267 143L377 103" stroke="#a6b99e" stroke-width="12" fill="none"/><ellipse cx="145" cy="101" rx="70" ry="24" transform="rotate(18 145 101)" fill="#88aa92"/><ellipse cx="389" cy="101" rx="70" ry="24" transform="rotate(-18 389 101)" fill="#88aa92"/><circle cx="267" cy="63" r="13" fill="${w.tip==='shoot'?'#f0c896':'#b9c9aa'}"/><circle cx="180" cy="316" r="10" fill="${w.tip==='root'?'#f0c896':'#c7ac8d'}"/><circle cx="350" cy="316" r="10" fill="${w.tip==='root'?'#f0c896':'#c7ac8d'}"/><path d="M290 ${dir==='down'?115:263}V${dir==='down'?263:115}" stroke="${sugar?'#e5b28b':'#8fb9cb'}" stroke-width="5"/><path d="M290 ${dir==='down'?263:115}l-9 ${dir==='down'?-15:15}h18Z" fill="#e8cfa7"/>${text(145,59,'Leaf',16)}${text(363,195,'Stem',16)}${text(130,291,'Roots',16)}${text(267,348,sugar?'Phloem: source leaf → destination':'Xylem: roots → stem → leaves',17)}`,'Whole plant organ system with roots stem leaves and selected transport direction');}
export function potometerFigure(w={}){let x=420-Math.min(25,Number(w.distance)||0)*7.5;return svg(`<path d="M87 88V244H470" fill="none" stroke="#b7d0da" stroke-width="25"/><path d="M87 88V244H470" fill="none" stroke="#315566" stroke-width="16"/><path d="M87 88V43M87 81L43 57M87 81L132 57" stroke="#a0b698" stroke-width="9"/><ellipse cx="43" cy="55" rx="32" ry="10" fill="#89aa91"/><ellipse cx="132" cy="55" rx="32" ry="10" fill="#89aa91"/><rect x="76" y="103" width="23" height="23" fill="#d5ad91"/><path d="M397 236V122" stroke="#9cb8c7" stroke-width="12"/><rect x="372" y="78" width="50" height="45" fill="#8db7c799" stroke="#d8e5e9"/><path d="M383 166H410" stroke="#e7bc95" stroke-width="5"/><ellipse cx="${x}" cy="244" rx="12" ry="7" fill="#faf3e2"/>${Array.from({length:9},(_,i)=>`<path d="M${180+i*30} 265v10" stroke="#c7d8e0"/>`+text(180+i*30,293,String(32-i*4),12)).join('')}${text(265,328,'Capillary distance / mm',17)}${text(199,110,'Airtight seal',14)}${text(435,58,'Reservoir',14)}${text(284,190,'Bubble moves towards shoot',17)}`,'Bubble potometer schematic with shoot airtight seal capillary scale reset reservoir and bubble');}
export function sampleFigure(side='lower',index=0){let count=(side==='upper'?[2,1,3]:[12,10,14])[index]||0,body='<rect x="90" y="47" width="350" height="245" rx="5" fill="#bed0bc22" stroke="#c5d7cb"/>';for(let i=0;i<count;i++){let x=125+(i%5)*65,y=90+Math.floor(i/5)*74;body+=`<ellipse cx="${x-7}" cy="${y}" rx="9" ry="16" fill="#9ab8a1"/><ellipse cx="${x+7}" cy="${y}" rx="9" ry="16" fill="#9ab8a1"/><path d="M${x} ${y-10}v20" stroke="#233f4e" stroke-width="3"/>`;}return svg(body+text(270,28,`${side==='upper'?'Upper':'Lower'} surface · field${index+1}`,20)+text(270,326,'Field 0.5 × 0.5 mm = 0.25 mm²',17)+text(270,350,'Original schematic · count pores, not individual guard cells',13),'Schematic stomata field; pore count must be determined by learner');}
export function plantGraph(points=[]){let b='<path d="M65 30V280H490" stroke="#c1d1da" stroke-width="2" fill="none"/>';for(let i=0;i<=6;i++)b+=text(52,285-i*38,String(i),16,'end');for(let x of[15,20,25,30,35])b+=text(65+(x-15)*20,308,String(x),16);for(let [x,y]of points)b+=`<circle cx="${65+(x-15)*20}" cy="${280-Number(y)*38}" r="7" fill="#e6b492"/>`;return svg(b+text(275,344,'Temperature / °C',19)+text(275,21,'Uptake distance rate / mm per min',18),'Original temperature versus uptake-distance-rate graph; no trend inference is supplied');}
